#include <vector>

std::vector<int> evensOnly(const std::vector<int>& values)
{
    std::vector<int> evens{};
    for (int value : values)
    {
        if (value % 2 == 0)
        {
            evens.push_back(value);
        }
    }
    return evens;
}

unitTests:
TEST("mixed") { CHECK_EQ(evensOnly({ 1, 2, 3, 4, 5, 6 }), (std::vector<int>{ 2, 4, 6 })); }
TEST("keeps the order and the duplicates") { CHECK_EQ(evensOnly({ 8, 3, 8, 2 }), (std::vector<int>{ 8, 8, 2 })); }
TEST("none even") { CHECK(evensOnly({ 1, 3, 5 }).empty()); CHECK(evensOnly({}).empty()); }

